Item.method_code:
string expressionItemTypeId = this.getAttribute("typeId");
string expressionItemId = this.getID();

Item getPermissionsItem = this.newItem("Method", "effs_getExpressionPermissions");
getPermissionsItem.setProperty("access_type", "can_update");
getPermissionsItem.setProperty("expression_itemtype_id", expressionItemTypeId);
getPermissionsItem.setProperty("expression_item_id", expressionItemId);

getPermissionsItem = getPermissionsItem.apply();

if (getPermissionsItem.isError())
{
	return getPermissionsItem;
}

if (string.Equals("0", getPermissionsItem.getResult(), StringComparison.OrdinalIgnoreCase))
{
	return this.getInnovator().newError(CCO.ErrorLookup.Lookup("Aras.Server.Core.InsufficientPermissionsException", "add"));
}

return this;
